export async function listTools() {
  return [
    {
      name: 'inventory_search',
      description: 'Search product inventory by name',
      inputSchema: {
        type: 'object',
        properties: {
          query: { type: 'string', description: 'Search query matched against product names (case-insensitive)' },
          limit: { type: 'integer', description: 'Maximum number of results to return (1-10)', minimum: 1, maximum: 10 }
